async function addCustomers() {
  try {
    // ========== 1. ADD CUSTOMERS ==========
    console.log('👥 Adding new customers...');
    
    const { data: newCustomers, error: customerError } = await supabase
      .from('Customer')
      .insert(NEW_CUSTOMERS)
      .select();
    
    if (customerError) {
      console.error('❌ Error adding customers:', customerError);
      console.error('Full error details:', JSON.stringify(customerError, null, 2));
      // Check if error is due to duplicate emails
      if (customerError.code === '23505') {
        console.log('ℹ️  Some customers already exist (duplicate emails)');
        console.log('   Fetching existing customers instead...\n');
      }
    } else {
      console.log(`✅ Added ${newCustomers.length} new customers\n`);
    }

    // Fetch all customers
    const { data: allCustomers, error: fetchError } = await supabase
      .from('Customer')
      .select('*');
    
    if (fetchError) {
      console.error('❌ Error fetching customers:', fetchError.message);
      return;
    }

    console.log(`📊 Total customers in database: ${allCustomers.length}\n`);
    console.log('Customer Tier Distribution:');
    const tierCounts = allCustomers.reduce((acc, c) => {
      acc[c.customer_tier] = (acc[c.customer_tier] || 0) + 1;
      return acc;
    }, {});
    Object.entries(tierCounts).forEach(([tier, count]) => {
      console.log(`   ${tier}: ${count} customers`);
    });
    console.log();

    // ========== 2. POPULATE CUSTOMERS IN-STORE ==========
    console.log('🏪 Adding customers currently in-store...');
    
    // Select 7 random customers to be in-store
    const customersToAddInStore = allCustomers
      .sort(() => 0.5 - Math.random())
      .slice(0, Math.min(7, allCustomers.length));

    const customersInStore = customersToAddInStore.map(customer => ({
      customer_id: customer.id,
      email: customer.email
    }));

    // Clear existing in-store records first
    const { error: deleteError } = await supabase
      .from('customers_instore')
      .delete()
      .neq('id', '00000000-0000-0000-0000-000000000000'); // Delete all

    if (deleteError) {
      console.log(`   ⚠️  Could not clear existing records: ${deleteError.message}`);
    }

    // Insert new in-store records
    const { error: inStoreError } = await supabase
      .from('customers_instore')
      .insert(customersInStore);
    
    if (inStoreError) {
      console.error(`   ❌ Error: ${inStoreError.message}`);
    } else {
      console.log(`   ✅ Added ${customersInStore.length} customers currently in-store`);
      console.log('\n   Customers in-store:');
      customersToAddInStore.forEach((c, i) => {
        console.log(`   ${i + 1}. ${c.name} (${c.customer_tier})`);
      });
    }

    // ========== 3. VERIFY DATA ==========
    console.log('\n📊 Final Database Verification:');
    
    const { count: customerCount } = await supabase
      .from('Customer')
      .select('*', { count: 'exact', head: true });
    
    const { count: inStoreCount } = await supabase
      .from('customers_instore')
      .select('*', { count: 'exact', head: true });
    
    console.log(`   ✅ Customer table: ${customerCount} rows`);
    console.log(`   ✅ customers_instore table: ${inStoreCount} rows`);

    console.log('\n═'.repeat(60));
    console.log('✅ CUSTOMER DATA POPULATION COMPLETED!');
    console.log('═'.repeat(60));
    console.log('\n📱 You can now:');
    console.log('   • View customer segments on Promotions page');
    console.log('   • Track in-store customers');
    console.log('   • Assign tier-based discounts');
    console.log('   • Send targeted notifications\n');

  } catch (error) {
    console.error('\n❌ Fatal error:', error.message);
    process.exit(1);
  }
}

addCustomers();
